/* StayQuest - Travel Landing Page Styles */
:root {
  --primary-navy: #003B95;
  --accent-blue: #006CE4;
  --highlight-gold: #FFB700;
  --white: #ffffff;
  --light-gray: #f5f5f5;
  --text-dark: #1a1a1a;
  --text-muted: #6b6b6b;
