  font-size: 14px;
  font-weight: 500;
  color: var(--text-dark);
  padding: 8px 0;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.nav-actions {
  display: flex;
  gap: 12px;
}

.btn {
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--accent-blue);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-navy);
}

.btn-secondary {
  background: transparent;
  color: var(--text-dark);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background: var(--light-gray);
}

.btn-gold {
  background: var(--highlight-gold);
  color: var(--text-dark);
}

.btn-gold:hover {
  background: #e6a500;
}

