/* StayQuest - Travel Landing Page Styles */
:root {
  --primary-navy: #003B95;
  --accent-blue: #006CE4;
  --highlight-gold: #FFB700;
  --white: #ffffff;
  --light-gray: #f5f5f5;
  --text-dark: #1a1a1a;
  --text-muted: #6b6b6b;
  --border-color: #e0e0e0;
  --shadow: 0 2px 8px rgba(0,0,0,0.1);
  --shadow-lg: 0 4px 16px rgba(0,0,0,0.12);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Inter', 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text-dark);
  line-height: 1.6;
  background: var(--white);
}

a {
  text-decoration: none;
  color: inherit;
}

img {
  max-width: 100%;
  height: auto;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header / Navigation */
.header {
  background: var(--white);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  max-width: 1200px;
  margin: 0 auto;
}

.nav-logo {
  font-size: 24px;
  font-weight: 700;
  color: var(--primary-navy);
}

.nav-logo span {
  color: var(--highlight-gold);
}

.nav-links {
  display: flex;
  gap: 24px;
}

.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-dark);
  padding: 8px 0;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.nav-actions {
  display: flex;
  gap: 12px;
}

.btn {
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  border: none;
  transition: all 0.2s;
}

.btn-primary {
  background: var(--accent-blue);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--primary-navy);
}

.btn-secondary {
  background: transparent;
  color: var(--text-dark);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background: var(--light-gray);
}

.btn-gold {
  background: var(--highlight-gold);
  color: var(--text-dark);
}

.btn-gold:hover {
  background: #e6a500;
}

/* Hero Section */
.hero {
  background: linear-gradient(135deg, var(--primary-navy) 0%, #001a4d 100%);
  color: var(--white);
  padding: 60px 20px 80px;
  text-align: center;
}

.hero h1 {
  font-size: 42px;
  font-weight: 700;
  margin-bottom: 12px;
}

.hero p {
  font-size: 18px;
  opacity: 0.9;
  margin-bottom: 32px;
}

/* Search Form */
.search-form {
  background: var(--white);
  border-radius: 8px;
  padding: 16px;
  display: flex;
  gap: 12px;
  max-width: 900px;
  margin: 0 auto;
  box-shadow: var(--shadow-lg);
}

.search-field {
  flex: 1;
  position: relative;
}

.search-field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.search-field input,
.search-field select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 14px;
  color: var(--text-dark);
}

.search-field input:focus,
.search-field select:focus {
  outline: none;
  border-color: var(--accent-blue);
}

.search-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 20px;
}

.search-checkbox input {
  width: 16px;
  height: 16px;
  accent-color: var(--accent-blue);
}

.search-checkbox label {
  font-size: 13px;
  color: var(--text-dark);
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: 24px;
  overflow-x: auto;
}

.tab-btn {
  padding: 12px 20px;
  background: none;
  border: none;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all 0.2s;
}

.tab-btn:hover {
  color: var(--text-dark);
}

.tab-btn.active {
  color: var(--text-dark);
  border-bottom-color: var(--text-dark);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* Trust Badges */
.trust-badges {
  background: var(--light-gray);
  padding: 48px 20px;
}

.trust-badges .container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.trust-badge {
  text-align: center;
  padding: 20px;
}

.trust-badge-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  background: var(--white);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.trust-badge h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 4px;
}

.trust-badge p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Section Styles */
.section {
  padding: 48px 20px;
}

.section-header {
  text-align: center;
  margin-bottom: 32px;
}

.section-header h2 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 8px;
}

.section-header p {
  font-size: 16px;
  color: var(--text-muted);
}

/* Cards Grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.card {
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-image {
  height: 180px;
  background: var(--light-gray);
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-content {
  padding: 16px;
}

.card-content h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.card-content p {
  font-size: 14px;
  color: var(--text-muted);
}

.card-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 8px;
}

.card-price .current {
  font-size: 20px;
  font-weight: 700;
  color: var(--primary-navy);
}

.card-price .original {
  font-size: 14px;
  color: var(--text-muted);
  text-decoration: line-through;
}

.card-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 8px;
}

.rating-badge {
  background: var(--accent-blue);
  color: var(--white);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}

.rating-text {
  font-size: 13px;
  color: var(--text-muted);
}

/* Property Types Pills */
.property-types {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding: 32px 20px;
  background: var(--white);
}

.property-type {
  padding: 8px 16px;
  background: var(--light-gray);
  border-radius: 20px;
  font-size: 13px;
  color: var(--text-dark);
  transition: all 0.2s;
}

.property-type:hover {
  background: var(--primary-navy);
  color: var(--white);
}

/* Trip Planner */
.trip-planner {
  background: var(--light-gray);
  padding: 48px 20px;
}

.destination-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 16px;
}

.destination-card {
  background: var(--white);
  border-radius: 8px;
  padding: 16px;
  text-align: center;
  box-shadow: var(--shadow);
}

.destination-card h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.destination-card p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Carousel */
.carousel-section {
  padding: 48px 20px;
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
}

.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 8px 0;
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.carousel-card {
  min-width: 280px;
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.carousel-card .card-image {
  height: 160px;
}

.carousel-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  background: var(--white);
  border: none;
  border-radius: 50%;
  box-shadow: var(--shadow);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  z-index: 10;
  transition: background 0.2s;
}

.carousel-nav:hover {
  background: var(--light-gray);
}

.carousel-nav.prev {
  left: 0;
}

.carousel-nav.next {
  right: 0;
}

/* Weekend Deals */
.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 20px;
}

.deal-card {
  display: flex;
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.deal-card .card-image {
  width: 120px;
  min-width: 120px;
  height: auto;
}

.deal-card .card-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  padding: 20px 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-dark);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-question::after {
  content: '+';
  font-size: 20px;
  color: var(--text-muted);
  transition: transform 0.2s;
}

.faq-item.active .faq-question::after {
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 20px;
  font-size: 14px;
  color: var(--text-muted);
  line-height: 1.7;
}

/* Footer */
.footer {
  background: var(--primary-navy);
