.search-form {
  background: var(--white);
  border-radius: 8px;
  padding: 16px;
  display: flex;
  gap: 12px;
  max-width: 900px;
  margin: 0 auto;
  box-shadow: var(--shadow-lg);
}

.search-field {
  flex: 1;
  position: relative;
}

.search-field label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 4px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.search-field input,
.search-field select {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  font-size: 14px;
  color: var(--text-dark);
}

.search-field input:focus,
.search-field select:focus {
  outline: none;
  border-color: var(--accent-blue);
}

.search-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 20px;
}

.search-checkbox input {
  width: 16px;
  height: 16px;
  accent-color: var(--accent-blue);
}

.search-checkbox label {
  font-size: 13px;
  color: var(--text-dark);
}

