  white-space: nowrap;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  transition: all 0.2s;
}

.tab-btn:hover {
  color: var(--text-dark);
}

.tab-btn.active {
  color: var(--text-dark);
  border-bottom-color: var(--text-dark);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

