.trust-badges {
  background: var(--light-gray);
  padding: 48px 20px;
}

.trust-badges .container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.trust-badge {
  text-align: center;
  padding: 20px;
}

.trust-badge-icon {
