  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.trust-badge h3 {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 4px;
}

.trust-badge p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Section Styles */
.section {
  padding: 48px 20px;
}

.section-header {
  text-align: center;
  margin-bottom: 32px;
}

.section-header h2 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-dark);
  margin-bottom: 8px;
}

.section-header p {
  font-size: 16px;
  color: var(--text-muted);
}

/* Cards Grid */
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
}

.card {
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-image {
  height: 180px;
  background: var(--light-gray);
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-content {
  padding: 16px;
}

.card-content h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}

.card-content p {
  font-size: 14px;
  color: var(--text-muted);
}

.card-price {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-top: 8px;
}

.card-price .current {
  font-size: 20px;
  font-weight: 700;
  color: var(--primary-navy);
}

.card-price .original {
  font-size: 14px;
  color: var(--text-muted);
  text-decoration: line-through;
}

.card-rating {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 8px;
}

.rating-badge {
  background: var(--accent-blue);
  color: var(--white);
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
}

.rating-text {
  font-size: 13px;
  color: var(--text-muted);
}

/* Property Types Pills */
.property-types {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  padding: 32px 20px;
  background: var(--white);
}

.property-type {
  padding: 8px 16px;
  background: var(--light-gray);
  border-radius: 20px;
  font-size: 13px;
  color: var(--text-dark);
  transition: all 0.2s;
}

.property-type:hover {
  background: var(--primary-navy);
  color: var(--white);
}

