  gap: 16px;
}

.destination-card {
  background: var(--white);
  border-radius: 8px;
  padding: 16px;
  text-align: center;
  box-shadow: var(--shadow);
}

.destination-card h4 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
}

.destination-card p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Carousel */
.carousel-section {
  padding: 48px 20px;
  overflow: hidden;
}

.carousel-wrapper {
  position: relative;
}

.carousel {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-behavior: smooth;
  padding: 8px 0;
  -ms-overflow-style: none;
  scrollbar-width: none;
