  text-align: center;
}

.cta-banner h2 {
  font-size: 28px;
  font-weight: 700;
  margin-bottom: 8px;
}

.cta-banner p {
  font-size: 16px;
  margin-bottom: 20px;
}

/* Lists with tabs */
.list-with-tabs {
  padding: 32px 20px;
}

.list-item {
  padding: 12px 0;
  border-bottom: 1px solid var(--border-color);
}

.list-item h4 {
  font-size: 16px;
  font-weight: 600;
}

.list-item p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Rental company logos */
.company-logos {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: center;
  padding: 32px 20px;
  background: var(--white);
}

.company-logo {
  padding: 16px 24px;
  background: var(--light-gray);
  border-radius: 8px;
  font-weight: 700;
  font-size: 14px;
  color: var(--text-dark);
}

/* Destination tabs grid */
.dest-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 20px;
}

.dest-card {
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow);
}

.dest-card .card-image {
  height: 140px;
}

.dest-card .card-content {
  padding: 12px 16px;
}

.dest-card h4 {
  font-size: 15px;
  font-weight: 600;
}

.dest-card p {
  font-size: 13px;
  color: var(--text-muted);
}

/* Benefits */
.benefits-grid {
