  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  max-width: 900px;
  margin: 0 auto;
  padding: 32px 20px;
}

.benefit {
  text-align: center;
}

.benefit-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  background: var(--light-gray);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
}

.benefit h3 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 4px;
}

.benefit p {
  font-size: 14px;
  color: var(--text-muted);
}

/* Responsive */
@media (max-width: 768px) {
